  "inlineSchema": "// Lược đồ cơ sở dữ liệu của Vào Nghề.\n//\n// Sinh client:  pnpm exec nx run @datn/api:prisma-generate\n// Tạo migration: pnpm exec prisma migrate dev --schema apps/api/prisma/schema.prisma\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\n// Prisma 7 không nhận chuỗi kết nối trong file lược đồ nữa:\n//   - migrate/introspect đọc `datasource.url` trong apps/api/prisma.config.ts\n//     (DIRECT_URL, cổng 5432 — chế độ session, vì chế độ transaction không\n//     giữ được prepared statement nên không migrate được)\n//   - lúc chạy, PrismaService dựng client với adapter pg trỏ vào DATABASE_URL\n//     (cổng 6543 — pooler, chịu được nhiều kết nối ngắn)\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// Ba vai trò theo docs/report.md §5.5.\nenum Role {\n  USER // học sinh hoặc phụ huynh\n  CONTRIBUTOR // cựu sinh viên hoặc cố vấn\n  ADMIN\n}\n\nenum ConsentMethod {\n  GUARDIAN_EMAIL\n}\n\n// ══ Danh tính ══════════════════════════════════════════════════════════\n\nmodel User {\n  id           String    @id @default(cuid())\n  username     String    @unique\n  /// Có thể rỗng: tài khoản chỉ dùng tên đăng nhập thì chưa cần email.\n  email        String?   @unique\n  displayName  String\n  /// Rỗng với tài khoản chỉ đăng nhập bằng Google.\n  passwordHash String?\n  role         Role      @default(USER)\n  /// Dùng để tính xem có cần người giám hộ đồng ý không.\n  dateOfBirth  DateTime? @db.Date\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  oauthAccounts OAuthAccount[]\n  refreshTokens RefreshToken[]\n  consent       ParentalConsent?\n  gameProfile   GameProfile?\n  runs          ScenarioRun[]\n  bandSkills    UserBandSkill[]\n  eventAnswers  EventAnswer[]\n}\n\n/// Liên kết nhà cung cấp đăng nhập. Bảng riêng thay vì cột `googleId` để\n/// thêm nhà cung cấp thứ hai chỉ là thêm dòng, và một người có thể vừa có\n/// mật khẩu vừa có liên kết Google.\nmodel OAuthAccount {\n  id                String   @id @default(cuid())\n  userId            String\n  provider          String\n  providerAccountId String\n  createdAt         DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n  @@index([userId])\n}\n\n/// Token làm mới, lưu dạng băm và xoay vòng mỗi lần dùng.\n///\n/// `replacedById` nối các token thành một chuỗi. Nếu một token đã thu hồi\n/// lại được đem ra dùng, nghĩa là nó đã bị lộ — thu hồi cả chuỗi.\nmodel RefreshToken {\n  id           String    @id @default(cuid())\n  userId       String\n  tokenHash    String    @unique\n  expiresAt    DateTime\n  revokedAt    DateTime?\n  replacedById String?\n  userAgent    String?\n  createdAt    DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n/// Đồng ý của người giám hộ cho tài khoản dưới 16 tuổi (Nghị định 13/2023/NĐ-CP).\n/// Bản đồ án ghi nhận chứ chưa xác minh — giao diện nói rõ điều đó.\nmodel ParentalConsent {\n  id            String        @id @default(cuid())\n  userId        String        @unique\n  guardianName  String\n  guardianEmail String\n  method        ConsentMethod @default(GUARDIAN_EMAIL)\n  consentedAt   DateTime      @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// ══ Tiến trình chơi ════════════════════════════════════════════════════\n\n/// Phần hồ sơ không mở khoá gì cả: chân dung tính cách và các mốc đã qua.\nmodel GameProfile {\n  userId       String   @id\n  /// CHỈ phần chân dung đến từ bài tự vấn.\n  ///\n  /// Phần đến từ nhiệm vụ phụ không lưu ở đây mà cộng lại từ bảng EventAnswer\n  /// mỗi lần đọc. Giữ một nguồn cho mỗi thứ thì không bao giờ có chuyện tổng\n  /// và các phần cộng lại ra hai số khác nhau.\n  quizFit      Json     @default(\"{}\")\n  quizDone     Boolean  @default(false)\n  eventsPlayed Int      @default(0)\n  updatedAt    DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n/// Một lượt chơi kịch bản sâu.\n///\n/// `seed` do máy chủ phát lúc mở màn; `actions` là chuỗi hành động máy khách\n/// gửi lên khi kết thúc. Giữ cả hai nghĩa là mọi điểm đã trao đều tái dựng\n/// lại được — không phải tin, mà kiểm được.\nmodel ScenarioRun {\n  id            String    @id @default(cuid())\n  userId        String\n  scenarioKey   String\n  roleCode      String\n  band          String\n  seed          BigInt\n  actions       Json?\n  startedAt     DateTime  @default(now())\n  completedAt   DateTime?\n  endingId      String?\n  endingType    String?\n  pointsAwarded Int       @default(0)\n  /// Người chơi chấm tình huống có giống thực tế không (1–5 sao).\n  rating        Int?\n\n  user     User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  evidence RunEvidence[]\n\n  @@index([userId, completedAt])\n  @@index([userId, scenarioKey])\n}\n\n/// Bằng chứng do máy chủ chấm lại, không phải điều máy khách khai.\nmodel RunEvidence {\n  id         String  @id @default(cuid())\n  runId      String\n  activityId String\n  skill      String\n  /// \"+2\" | \"0\" | \"-1\"\n  anchor     String\n  /// Đã bị hạ trần vì người chơi xem gợi ý.\n  capped     Boolean @default(false)\n  why        String\n  quote      String?\n  timeout    Boolean @default(false)\n\n  run ScenarioRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  @@index([runId])\n}\n\n/// Tổng điểm kỹ năng theo (người chơi, nghề, cấp bậc).\n///\n/// Suy ra được từ RunEvidence, nhưng giữ sẵn ở đây vì đây là số được đọc mỗi\n/// lần kiểm \"cấp bậc này đã mở chưa\" — một lần đọc có chỉ mục thay vì gộp\n/// toàn bộ bằng chứng.\nmodel UserBandSkill {\n  id       String @id @default(cuid())\n  userId   String\n  roleCode String\n  band     String\n  points   Int    @default(0)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, roleCode, band])\n  @@index([userId])\n}\n\n/// Một lựa chọn ở nhiệm vụ phụ. Máy chủ tra tín hiệu từ bộ dữ liệu rồi cộng\n/// vào chân dung, nên vector tính cách cũng là suy ra chứ không phải gửi lên.\nmodel EventAnswer {\n  id          String   @id @default(cuid())\n  userId      String\n  eventId     String\n  roleCode    String\n  band        String\n  choiceIndex Int\n  answeredAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, eventId])\n  @@index([userId])\n}\n",
